{
  "name": "dead-hour",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "DEAD HOUR - a first-person open-world zombie survival experience",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
