  },
  "dependencies": {
    "@fontsource/barlow-condensed": "^5.2.8",
    "@fontsource/inter": "^5.2.8",
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^8.3.5"
  }
}

:root {
  --bone: #e9e4d8;
  --bone-dim: #a49e90;
  --bone-faint: #6c6a61;
  --ember: #d25732;
  --ember-bright: #f07a4a;
  --amber: #d9b867;
  --sage: #aab88e;
  --ink: #0a0b0a;
  --panel: rgba(12, 13, 12, 0.72);
  --hair: rgba(233, 228, 216, 0.16);
  --hair-strong: rgba(233, 228, 216, 0.32);
  --danger: #b94a3c;
  --font-display: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --ease: cubic-bezier(0.22, 0.8, 0.2, 1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background: #080908;
  color: var(--bone);
  font-family: var(--font-body);
  overflow: hidden;
  user-select: none;
  -webkit-font-smoothing: antialiased;
}
button { font-family: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
#app, #game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
#game { background: #161813; }
.hidden { display: none !important; }
svg { width: 100%; height: 100%; fill: currentColor; }

/* ==========================================================
   SCREEN FX
   ========================================================== */
#screen-fx { position: fixed; inset: 0; pointer-events: none; z-index: 5; }
.fx-vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 38%, rgba(5, 6, 5, 0.38) 86%, rgba(3, 4, 3, 0.72) 100%),
    linear-gradient(to bottom, rgba(8, 9, 7, 0.2), transparent 16%, transparent 82%, rgba(5, 6, 3, 0.34));
}
.fx-grain {
  position: absolute; inset: -50%; opacity: 0.05; pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grain 0.6s steps(2) infinite;
}
@keyframes grain {
  0% { transform: translate(0, 0); } 25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); } 75% { transform: translate(-1%, 2%); }
  100% { transform: translate(2%, -1%); }
}
.fx-scan {
  position: absolute; inset: 0; opacity: .12; mix-blend-mode: overlay;
  background: repeating-linear-gradient(to bottom, transparent 0 2px, rgba(0,0,0,.4) 2px 3px);
}

/* ==========================================================
   HUD
   ========================================================== */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; animation: hudIn .7s var(--ease) both; }
@keyframes hudIn { from { opacity: 0; } to { opacity: 1; } }
.hud-top { position: absolute; top: 0; left: 0; right: 0; display: flex; justify-content: space-between; align-items: flex-start; padding: 26px 34px; }

.quest { min-width: 280px; padding-left: 13px; border-left: 2px solid var(--ember); filter: drop-shadow(0 2px 8px rgba(0,0,0,.55)); }
.quest-kicker { display: flex; align-items: center; gap: 7px; font-family: var(--font-display); font-size: 10px; letter-spacing: .28em; color: var(--bone-dim); margin-bottom: 6px; }
.quest-dot { width: 5px; height: 5px; background: var(--ember); border-radius: 50%; box-shadow: 0 0 8px var(--ember); animation: pulse 2.4s infinite; }
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: .3; } }
.quest-title { font-family: var(--font-display); font-size: 23px; line-height: 1.05; letter-spacing: .035em; font-weight: 500; text-transform: uppercase; }
.quest-sub { font-size: 10.5px; letter-spacing: .12em; color: var(--amber); margin-top: 5px; text-transform: uppercase; }

.compass-wrap { position: relative; width: 380px; height: 78px; margin-top: -4px; overflow: hidden; mask-image: linear-gradient(to right, transparent, #000 15%, #000 85%, transparent); }
.compass-notches { position: absolute; top: 26px; left: 0; right: 0; height: 5px; opacity: .45;
  background: repeating-linear-gradient(to right, var(--bone) 0 1px, transparent 1px 19px); }
.compass-strip { position: absolute; top: 14px; left: 0; display: flex; gap: 55px; white-space: nowrap; font-family: var(--font-display); font-size: 11px; letter-spacing: .2em; color: var(--bone-dim); will-change: transform; }
.compass-strip span { width: 20px; text-align: center; }
.compass-head { position: absolute; top: 30px; left: 50%; transform: translateX(-50%); font-family: var(--font-display); font-size: 19px; font-weight: 600; letter-spacing: .16em; color: var(--bone); text-shadow: 0 2px 6px #000; }
.compass-degree { position: absolute; top: 51px; left: 50%; transform: translateX(-50%); font-family: var(--font-display); font-size: 9.5px; letter-spacing: .22em; color: var(--ember-bright); }
.compass-marker { position: absolute; top: 0; left: 50%; width: 1px; height: 100%; }
.compass-marker i { position: absolute; top: 34px; left: 50%; width: 0; height: 0; transform: translateX(-50%); border-left: 5px solid transparent; border-right: 5px solid transparent; border-top: 7px solid var(--amber); filter: drop-shadow(0 0 5px rgba(217,184,103,.7)); }
.compass-marker.off { opacity: .45; }

.world-clock { text-align: right; min-width: 200px; filter: drop-shadow(0 2px 8px rgba(0,0,0,.55)); }
.clock-row { display: flex; gap: 10px; justify-content: flex-end; align-items: center; font-family: var(--font-display); font-size: 12px; letter-spacing: .14em; color: var(--bone-dim); }
#clock { font-size: 22px; color: var(--bone); letter-spacing: .06em; font-variant-numeric: tabular-nums; }
.live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--ember); box-shadow: 0 0 7px var(--ember); }
.weather-row { display: flex; justify-content: flex-end; gap: 10px; margin-top: 2px; font-family: var(--font-display); font-size: 10px; letter-spacing: .19em; color: var(--bone-dim); text-transform: uppercase; }
#temp { color: var(--amber); }
.clock-dial { position: relative; width: 116px; height: 3px; background: rgba(255,255,255,.13); margin: 8px 0 0 auto; overflow: hidden; }
.dial-fill { height: 100%; width: 55%; background: linear-gradient(to right, var(--ember), var(--amber)); }
.dial-hand { position: absolute; top: -2px; height: 7px; width: 2px; background: var(--bone); left: 55%; }

.hud-side { position: absolute; top: 142px; right: 34px; display: flex; flex-direction: column; align-items: flex-end; gap: 20px; }
.noise-meter { display: flex; align-items: center; gap: 9px; opacity: .8; transition: opacity .3s; }
.noise-label { font-family: var(--font-display); font-size: 9px; letter-spacing: .24em; color: var(--bone-dim); }
.noise-bars { display: flex; gap: 2px; align-items: flex-end; height: 11px; }
.noise-bars i { width: 2px; height: 4px; background: var(--bone-faint); transition: background .2s, height .2s; }
.noise-bars i:nth-child(2) { height: 6px; } .noise-bars i:nth-child(3) { height: 8px; } .noise-bars i:nth-child(4) { height: 10px; }
.noise-bars i:nth-child(5) { height: 8px; } .noise-bars i:nth-child(6) { height: 6px; } .noise-bars i:nth-child(7) { height: 4px; } .noise-bars i:nth-child(8) { height: 3px; }
.noise-bars i.on { background: var(--amber); }
.noise-bars.hot i.on { background: var(--ember); }

.notifications { display: flex; flex-direction: column; gap: 7px; align-items: flex-end; }
.toast {
  display: flex; align-items: center; gap: 10px; padding: 7px 12px 7px 9px; min-width: 210px;
  background: linear-gradient(to right, rgba(12,13,11,.82), rgba(12,13,11,.5));
  border-left: 1px solid var(--amber); backdrop-filter: blur(6px);
  animation: toastIn .35s var(--ease) both;
}
.toast.out { animation: toastOut .4s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(12px); } }
.toast .t-ico { width: 24px; height: 24px; display: grid; place-items: center; color: var(--amber); }
.toast .t-ico svg { width: 19px; height: 19px; }
.toast .t-main { font-family: var(--font-display); font-size: 12.5px; letter-spacing: .1em; text-transform: uppercase; }
.toast .t-sub { font-size: 9.5px; color: var(--bone-dim); letter-spacing: .08em; margin-top: 1px; }
.toast.danger { border-left-color: var(--danger); }
.toast.danger .t-ico { color: var(--danger); }
.toast.good { border-left-color: var(--sage); }
.toast.good .t-ico { color: var(--sage); }

.hud-bottom { position: absolute; left: 0; right: 0; bottom: 0; display: flex; justify-content: space-between; align-items: flex-end; padding: 0 34px 30px; }
.vitals { width: 296px; filter: drop-shadow(0 3px 10px rgba(0,0,0,.6)); }
.vital { display: flex; align-items: center; gap: 9px; margin-bottom: 7px; }
.vital svg { width: 16px; height: 16px; flex: none; }
.vital-health svg { color: #c9604d; }
.vital-stamina svg { color: var(--sage); }
.vital-track { position: relative; flex: 1; height: 5px; background: rgba(235,229,214,.12); overflow: hidden; }
.vital-track::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(to right, transparent 0 23px, rgba(8,9,8,.55) 23px 24px); }
.vital-fill { height: 100%; width: 100%; background: linear-gradient(to right, #8f3d31, #c9604d); transition: width .25s ease; box-shadow: 0 0 10px rgba(201,96,77,.28); }
.vital-stamina .vital-fill { background: linear-gradient(to right, #77865c, #b4c294); width: 100%; }
.vital-num { font-family: var(--font-display); font-size: 12px; color: var(--bone); width: 25px; text-align: right; letter-spacing: .06em; }
.vital-row { display: flex; gap: 13px; margin-top: 11px; }
.micro-vital { display: flex; align-items: center; gap: 5px; flex: 1; }
.micro-icon { font-size: 10px; color: var(--bone-dim); }
.micro-icon.drop { color: #7e9eaa; }
.infection .micro-icon { color: #7f8d5d; }
.micro-track { flex: 1; height: 2px; background: rgba(235,229,214,.13); }
.micro-track i { display: block; height: 100%; width: 80%; background: var(--amber); transition: width .3s; }
.micro-vital:nth-child(2) .micro-track i { background: #7e9eaa; }
.infection .micro-track i { background: #8c9a63; }
.micro-vital b { font-family: var(--font-display); font-size: 9px; font-weight: 400; color: var(--bone-dim); width: 15px; text-align: right; }

.quickbar { display: flex; gap: 5px; align-items: flex-end; margin-bottom: 1px; pointer-events: auto; }
.quick {
  position: relative; width: 37px; height: 37px; display: grid; place-items: center;
  background: rgba(11,12,10,.58); border: 1px solid rgba(233,228,216,.12); backdrop-filter: blur(5px);
  transition: border-color .2s, background .2s;
}
.quick:hover { border-color: var(--hair-strong); background: rgba(20,21,18,.7); }
.quick.active { border-color: var(--amber); background: rgba(65,52,28,.4); }
.quick .q-key { position: absolute; top: 1px; left: 3px; font-family: var(--font-display); font-size: 8px; color: var(--bone-faint); }
.quick .q-ico { width: 21px; height: 21px; color: var(--bone-dim); }
.quick.active .q-ico { color: var(--amber); }
.quick .q-count { position: absolute; bottom: 1px; right: 3px; font-family: var(--font-display); font-size: 8px; color: var(--bone-dim); }

.weapon-panel { width: 246px; text-align: right; filter: drop-shadow(0 3px 10px rgba(0,0,0,.6)); }
.weapon-meta { display: flex; justify-content: flex-end; gap: 12px; font-family: var(--font-display); font-size: 8.5px; letter-spacing: .25em; color: var(--bone-faint); text-transform: uppercase; }
#weapon-cond { color: var(--sage); }
.weapon-name { font-family: var(--font-display); font-size: 16px; letter-spacing: .13em; margin-top: 2px; color: var(--bone); }
.ammo-row { display: flex; justify-content: flex-end; align-items: center; gap: 13px; margin-top: 1px; }
.ammo { display: flex; align-items: baseline; gap: 5px; font-family: var(--font-display); }
#ammo { font-size: 39px; line-height: .9; letter-spacing: .02em; font-weight: 300; }
#ammo-reserve { font-size: 13px; color: var(--bone-dim); font-style: normal; letter-spacing: .1em; }
#ammo-reserve:empty { display: none; }
.weapon-icon { color: var(--bone-dim); width: 64px; opacity: .72; }
.repair-track { height: 2px; width: 100%; background: rgba(233,228,216,.1); margin-top: 7px; overflow: hidden; }
.repair-track i { display: block; height: 100%; width: 98%; background: var(--sage); transition: width .3s; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 28px; height: 28px; transform: translate(-50%,-50%); transition: transform .15s, opacity .2s; }
.crosshair i { position: absolute; background: rgba(238,233,221,.82); box-shadow: 0 0 3px rgba(0,0,0,.9); transition: all .18s var(--ease); }
.ch-t { top: 1px; left: 50%; width: 1px; height: 7px; transform: translateX(-50%); }
.ch-b { bottom: 1px; left: 50%; width: 1px; height: 7px; transform: translateX(-50%); }
.ch-l { left: 1px; top: 50%; height: 1px; width: 7px; transform: translateY(-50%); }
.ch-r { right: 1px; top: 50%; height: 1px; width: 7px; transform: translateY(-50%); }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 2px; height: 2px; background: rgba(238,233,221,.8); border-radius: 50%; transform: translate(-50%,-50%); }
.crosshair.ads i { opacity: .25; }
.crosshair.ads { transform: translate(-50%,-50%) scale(.7); }
.crosshair.melee .ch-t, .crosshair.melee .ch-b, .crosshair.melee .ch-l, .crosshair.melee .ch-r { opacity: .38; }
.crosshair.hidden { opacity: 0; }
.hitmarker { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%,-50%) rotate(45deg); opacity: 0; }
