@keyframes hit { 0% { opacity: 1; transform: translate(-50%,-50%) rotate(45deg) scale(.6); } 60% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%,-50%) rotate(45deg) scale(1.05); } }
.hitmarker i { position: absolute; background: #f2dfc8; }
.hitmarker i:nth-child(1) { top: 0; left: 0; width: 1px; height: 8px; }
.hitmarker i:nth-child(2) { bottom: 0; right: 0; width: 1px; height: 8px; }
.hitmarker i:nth-child(3) { top: 0; right: 0; height: 1px; width: 8px; }
.hitmarker i:nth-child(4) { bottom: 0; left: 0; height: 1px; width: 8px; }
