.interact { position: absolute; left: 50%; top: 58%; transform: translate(-50%, 0); display: flex; align-items: center; gap: 12px; opacity: 0; transition: opacity .2s, transform .2s; background: linear-gradient(90deg, transparent, rgba(8,9,8,.42) 18%, rgba(8,9,8,.42) 82%, transparent); padding: 7px 20px; }
