export function weedTexture() {
  return cached('weeds', () => {
    const w = 256, h = 256
    const c = document.createElement('canvas'); c.width = w; c.height = h
    const ctx = c.getContext('2d')
    const rng = mulberry32(303)
    for (let i = 0; i < 80; i++) {
      const x = 30 + rng() * (w - 60)
      const hh = 30 + rng() * 150
